using GraphApi.Models.JNT.JuntaDetalle;namespace GraphApi.Services.JNT.JuntaDetalle{    /// <summary>    /// Define las operaciones de negocio y persistencia para JuntaDetalles.    /// </summary>    public interface IJuntaDetalleService    {        /// <summary>        /// Obtiene la lista de JuntaDetalles con filtros opcionales.        /// </summary>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<clReadJuntaDetalle>> GetJuntaDetalles(            int userId,            string windowName);        /// <summary>        /// Obtiene la lista dinámica de JuntaDetalles con filtros opcionales.        /// </summary>        /// <param name="juntaDetalleID">Filtro opcional para JuntaDetalleID.</param>        /// <param name="juntaID">Filtro opcional para JuntaID.</param>        /// <param name="contenido">Filtro opcional para Contenido.</param>        /// <param name="fechaRegistro">Filtro opcional para FechaRegistro.</param>        /// <param name="bEliminado">Filtro opcional para bEliminado.</param>        /// <param name="columnNames">Nombres de columnas a retornar (separados por coma). Si es null o vacío, retorna columna por defecto.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<IEnumerable<dynamic>> GetJuntaDetallesDynamic(            int? juntaDetalleID,            int? juntaID,            string? contenido,            DateTime? fechaRegistro,            bool? bEliminado,            string? columnNames,            int userId,            string windowName);        /// <summary>        /// Crea un nuevo JuntaDetalle.        /// </summary>        /// <param name="objInput">Datos para crear el JuntaDetalle.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadJuntaDetalle> CreateJuntaDetalle(            clCreateJuntaDetalle objInput,            int userId,            string windowName);        /// <summary>        /// Actualiza campos selectivos de un JuntaDetalle.        /// </summary>        /// <param name="objInput">Datos para actualizar el JuntaDetalle, incluyendo su ID y campos a modificar.</param>        /// <param name="userId">ID de usuario (cabecera “UserID”).</param>        /// <param name="windowName">Nombre de aplicación (cabecera “WindowName”).</param>        Task<clReadJuntaDetalle?> UpdateJuntaDetalle(            clUpdateJuntaDetalle objInput,            int userId,            string windowName);        /// <summary>        /// Elimina un JuntaDetalle por su ID.        /// </summary>        /// <param name="nJuntaDetalleID">ID del JuntaDetalle a eliminar.</param>        Task<bool> DeleteJuntaDetalle(int nJuntaDetalleID);    }}